import * as React from "react";

import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { Slider } from "@/registry/erbium/ui/slider";

export function SliderControlled() {
  const [value, setValue] = React.useState([0.3, 0.7]);

  return (
    <Field className="mx-auto max-w-xs gap-3">
      <div className="flex items-center justify-between gap-2">
        <FieldLabel>Temperature</FieldLabel>
        <span className="text-sm text-muted-foreground">{value.join(", ")}</span>
      </div>
      <Slider
        value={value}
        onValueChange={(value) => setValue(value as number[])}
        min={0}
        max={1}
        step={0.1}
      />
    </Field>
  );
}

import { SliderControlled } from "../examples/upstream/slider-controlled";

const Example = () => <SliderControlled />;

export default Example;
